import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"会前资料","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/materials.md","filePath":"zh/guide/materials.md","lastUpdated":1793020783000}'),i={name:"zh/guide/materials.md"};function l(n,e,s,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="会前资料" tabindex="-1">会前资料 <a class="header-anchor" href="#会前资料" aria-label="Permalink to &quot;会前资料&quot;">​</a></h1><p>本页介绍如何把你自己和这场会议的背景告诉 MeetCue，让提示更贴近你真正会说的话。</p><h2 id="描述你的角色" tabindex="-1">描述你的角色 <a class="header-anchor" href="#描述你的角色" aria-label="Permalink to &quot;描述你的角色&quot;">​</a></h2><p>在 <strong>设置 › 提示 › 我的角色</strong> 中用一句话介绍自己，例如：</p><blockquote><p>网络架构师，8 年数据中心运维经验</p></blockquote><p>要点模型会从这个角度组织要点。</p><h2 id="添加文件" tabindex="-1">添加文件 <a class="header-anchor" href="#添加文件" aria-label="Permalink to &quot;添加文件&quot;">​</a></h2><ol><li>打开 <strong>设置 › 提示</strong>。</li><li>在 <strong>会前资料</strong> 下点击 <strong>添加文件…</strong>。</li><li>选择议程、简历、项目资料等文件。支持 <code>.txt</code>、<code>.md</code>、<code>.docx</code> 和 <code>.pdf</code>。</li></ol><p>MeetCue 在本机抽取文字并显示字数。没有文字层的扫描版 PDF 抽不出文字，请先用文字识别功能导出。</p><h2 id="会发送什么" tabindex="-1">会发送什么 <a class="header-anchor" href="#会发送什么" aria-label="Permalink to &quot;会发送什么&quot;">​</a></h2><ul><li>资料的一小段摘录会放进要点模型的指令中，让提示能提到你的项目和议程。</li><li>资料中最有辨识度的词（产品名、缩写、人名）会作为热词发给语音识别供应商，让这些词识别得更准。</li><li>全文只留在你的电脑上，也不会包含在诊断信息里。</li></ul><p>资料放在指令中整场会议都不变的部分。支持提示缓存的供应商从第二个问题起对这部分收费会低很多。</p><p>想配合模拟面试试一试，可以用示例职位描述：<a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-software-engineer.md" target="_blank" rel="noreferrer">jd-software-engineer.md</a> 或 <a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-security-ai.md" target="_blank" rel="noreferrer">jd-security-ai.md</a>。它们与<a href="/meetcue/zh/guide/mock-interview">模拟面试</a>中的内置示例面试对应。</p><h2 id="保持精简" tabindex="-1">保持精简 <a class="header-anchor" href="#保持精简" aria-label="Permalink to &quot;保持精简&quot;">​</a></h2><p>资料越长，每次请求越大、开始越慢。与会议相关的一两页资料，比整份文档库效果更好。不再需要的文件可以点 <strong>移除</strong>。</p>',15)])])}const u=a(i,[["render",l]]);export{p as __pageData,u as default};
